cypress_script:
describe('Forgot Password Recovery Form', () => {
  it('should retrieve password with a valid email', () => {
    cy.visit('https://the-internet.herokuapp.com/forgot_password');
    cy.get('input#email').type('test@example.com');
    cy.get('button#form_submit').click();
    cy.url().should('include', '/forgot_password');
    cy.get('div#flash-messages').should('be.visible');
  });

  it('should not change URL when submitting an empty form', () => {
    cy.visit('https://the-internet.herokuapp.com/forgot_password');
    cy.get('button#form_submit').click();
    cy.url().should('equal', 'https://the-internet.herokuapp.com/forgot_password');
    cy.get('div#flash-messages').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Forgot Password Recovery Form', () => {
  test('should retrieve password with a valid email', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/forgot_password');
    await page.fill('input#email', 'test@example.com');
    await page.click('button#form_submit');
    await expect(page).toHaveURL(/forgot_password/);
    await expect(page.locator('div#flash-messages')).toBeVisible();
  });

  test('should not change URL when submitting an empty form', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/forgot_password');
    await page.click('button#form_submit');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/forgot_password');
    await expect(page.locator('div#flash-messages')).toBeVisible();
  });
});
